// AUTO-GENERATED by Bloxks — do not edit. Overwritten on every build.
// Google sign-in button that follows Google's branding rules: the official
// multicolor "G" logo, Google's own colors and border, never redrawn.
// Give it the SAME height and cornerRadius as the Apple button so both match:
//   <AppleAuthentication.AppleAuthenticationButton cornerRadius={14} style={{ width: '100%', height: 50 }} … />
//   <GoogleSignInButton onPress={signInWithGoogle} height={50} cornerRadius={14} theme="light" />
// theme: "light" on a light screen (white + gray border), "dark" on a dark screen, "neutral" = light gray.
// kind: "continue" (default), "signin", "signup". Pass `text` only to follow the app's own language setting.
import React from 'react'
import { Image, Pressable, Text, View, type StyleProp, type ViewStyle } from 'react-native'

const G_LOGO = { uri: 'data:image/png;base64,' }

const THEMES = {
  light: { background: '#FFFFFF', border: '#747775', text: '#1F1F1F' },
  dark: { background: '#131314', border: '#8E918F', text: '#E3E3E3' },
  neutral: { background: '#F2F2F2', border: '#F2F2F2', text: '#1F1F1F' },
} as const

const LABELS = {
  continue: ['Continuer avec Google', 'Continue with Google'],
  signin: ['Se connecter avec Google', 'Sign in with Google'],
  signup: ['S’inscrire avec Google', 'Sign up with Google'],
} as const

function isFrench(): boolean {
  try {
    return Intl.DateTimeFormat().resolvedOptions().locale.toLowerCase().startsWith('fr')
  } catch {
    return false
  }
}

export interface GoogleSignInButtonProps {
  onPress: () => void
  theme?: keyof typeof THEMES
  kind?: keyof typeof LABELS
  /** Same value as the Apple button's height (default 50, never under 44). */
  height?: number
  /** Same value as the Apple button's cornerRadius (default 12). */
  cornerRadius?: number
  disabled?: boolean
  /** Label override, only to follow the app's in-app language setting. */
  text?: string
  style?: StyleProp<ViewStyle>
}

export function GoogleSignInButton({
  onPress,
  theme = 'light',
  kind = 'continue',
  height = 50,
  cornerRadius = 12,
  disabled = false,
  text,
  style,
}: GoogleSignInButtonProps) {
  const colors = THEMES[theme]
  const h = Math.max(44, height)
  const label = text ?? LABELS[kind][isFrench() ? 0 : 1]
  // Proportions du bouton officiel d'Apple : texte ≈ 38 % de la hauteur, logo ≈ 40 %.
  const fontSize = Math.min(20, Math.max(14, Math.round(h * 0.36)))
  const logo = Math.round(h * 0.4)
  return (
    <Pressable
      onPress={onPress}
      disabled={disabled}
      accessibilityRole="button"
      accessibilityLabel={label}
      accessibilityState={{ disabled }}
      style={({ pressed }) => [
        {
          width: '100%',
          height: h,
          borderRadius: cornerRadius,
          backgroundColor: colors.background,
          borderWidth: 1,
          borderColor: colors.border,
          opacity: disabled ? 0.6 : pressed ? 0.85 : 1,
          alignItems: 'center',
          justifyContent: 'center',
          paddingHorizontal: 12,
        },
        style,
      ]}
    >
      <View style={{ flexDirection: 'row', alignItems: 'center', gap: Math.round(h * 0.2) }}>
        <Image source={G_LOGO} style={{ width: logo, height: logo }} resizeMode="contain" />
        <Text numberOfLines={1} style={{ color: colors.text, fontSize, fontWeight: '500', letterSpacing: 0.25 }}>
          {label}
        </Text>
      </View>
    </Pressable>
  )
}
